CREATE TABLE public.entity_types (id uuid NOT NULL DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), version integer NOT NULL CHECK(version>0), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 100), type_key text NOT NULL CHECK(type_key ~ '^[a-z][a-z0-9_]{0,63}$'), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(id,version), UNIQUE(organization_id,id,version), UNIQUE(organization_id,type_key,version));
GRANT SELECT ON public.entity_types TO authenticated; GRANT ALL ON public.entity_types TO service_role;
ALTER TABLE public.entity_types ENABLE ROW LEVEL SECURITY;
CREATE POLICY types_read ON public.entity_types FOR SELECT TO authenticated USING(public.is_org_member(organization_id));
CREATE TABLE public.entity_field_definitions (organization_id uuid NOT NULL, entity_type_id uuid NOT NULL, configuration_version integer NOT NULL, field_key text NOT NULL CHECK(field_key ~ '^[a-z][a-z0-9_]{0,63}$' AND field_key NOT IN ('__proto__','constructor','prototype')), label text NOT NULL CHECK(length(label) BETWEEN 1 AND 100), field_type text NOT NULL CHECK(field_type IN ('text','textarea','number','boolean','date','email','url','select','relationship')), required boolean NOT NULL DEFAULT false, settings jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(settings)='object'), position integer NOT NULL DEFAULT 0, PRIMARY KEY(entity_type_id,configuration_version,field_key), FOREIGN KEY(organization_id,entity_type_id,configuration_version) REFERENCES public.entity_types(organization_id,id,version));
GRANT SELECT ON public.entity_field_definitions TO authenticated; GRANT ALL ON public.entity_field_definitions TO service_role;
ALTER TABLE public.entity_field_definitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY fields_read ON public.entity_field_definitions FOR SELECT TO authenticated USING(public.is_org_member(organization_id));
CREATE TABLE public.entity_type_layouts (organization_id uuid NOT NULL, entity_type_id uuid NOT NULL, configuration_version integer NOT NULL, layout jsonb NOT NULL CHECK(jsonb_typeof(layout)='object'), PRIMARY KEY(entity_type_id,configuration_version), FOREIGN KEY(organization_id,entity_type_id,configuration_version) REFERENCES public.entity_types(organization_id,id,version));
GRANT SELECT ON public.entity_type_layouts TO authenticated; GRANT ALL ON public.entity_type_layouts TO service_role;
ALTER TABLE public.entity_type_layouts ENABLE ROW LEVEL SECURITY;
CREATE POLICY layouts_read ON public.entity_type_layouts FOR SELECT TO authenticated USING(public.is_org_member(organization_id));
CREATE FUNCTION public.can_entity(p_org uuid,p_type uuid,p_action text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT public.is_org_member(p_org) AND EXISTS(SELECT 1 FROM public.organization_memberships m JOIN public.entity_type_layouts l ON l.organization_id=m.organization_id WHERE m.organization_id=p_org AND m.user_id=auth.uid() AND m.status='active' AND l.entity_type_id=p_type AND l.configuration_version=(SELECT max(t.version) FROM public.entity_types t WHERE t.id=p_type AND t.organization_id=p_org) AND (m.role_key IN ('owner','admin') OR (l.layout->'permissions'->p_action) ? m.role_key)) $$;
REVOKE ALL ON FUNCTION public.can_entity(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.can_entity(uuid,uuid,text) TO authenticated;
CREATE TABLE public.entities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, entity_type_id uuid NOT NULL, configuration_version integer NOT NULL, data jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(data)='object'), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), revision integer NOT NULL DEFAULT 1, UNIQUE(organization_id,id), FOREIGN KEY(organization_id,entity_type_id,configuration_version) REFERENCES public.entity_types(organization_id,id,version));
GRANT SELECT,INSERT,DELETE ON public.entities TO authenticated; GRANT UPDATE(data) ON public.entities TO authenticated; GRANT ALL ON public.entities TO service_role;
ALTER TABLE public.entities ENABLE ROW LEVEL SECURITY;
CREATE POLICY entities_read ON public.entities FOR SELECT TO authenticated USING(public.can_entity(organization_id,entity_type_id,'read'));
CREATE POLICY entities_create ON public.entities FOR INSERT TO authenticated WITH CHECK(created_by=auth.uid() AND public.can_entity(organization_id,entity_type_id,'create') AND public.can_entity(organization_id,entity_type_id,'read'));
CREATE POLICY entities_update ON public.entities FOR UPDATE TO authenticated USING(public.can_entity(organization_id,entity_type_id,'update') AND public.can_entity(organization_id,entity_type_id,'read')) WITH CHECK(public.can_entity(organization_id,entity_type_id,'update'));
CREATE POLICY entities_delete ON public.entities FOR DELETE TO authenticated USING(public.can_entity(organization_id,entity_type_id,'delete') AND public.can_entity(organization_id,entity_type_id,'read'));
CREATE INDEX entities_type_org ON public.entities(organization_id,entity_type_id,created_at DESC);
CREATE INDEX entities_data ON public.entities USING gin(data);
CREATE FUNCTION public.validate_entity_record() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ DECLARE f record; v jsonb; s text; target uuid; BEGIN
 IF TG_OP='INSERT' AND NEW.configuration_version<>(SELECT max(version) FROM public.entity_types WHERE id=NEW.entity_type_id AND organization_id=NEW.organization_id) THEN RAISE EXCEPTION 'Use latest configuration'; END IF;
 IF TG_OP='UPDATE' THEN IF NEW.organization_id<>OLD.organization_id OR NEW.entity_type_id<>OLD.entity_type_id OR NEW.configuration_version<>OLD.configuration_version OR NEW.created_by<>OLD.created_by THEN RAISE EXCEPTION 'Record identity is immutable'; END IF; NEW.data:=OLD.data || NEW.data; NEW.revision:=OLD.revision+1; END IF;
 NEW.updated_at:=now();
 FOR f IN SELECT * FROM public.entity_field_definitions WHERE organization_id=NEW.organization_id AND entity_type_id=NEW.entity_type_id AND configuration_version=NEW.configuration_version LOOP
 v:=NEW.data->f.field_key; s:=NEW.data->>f.field_key;
 IF v IS NULL OR v='null'::jsonb OR s='' THEN IF f.required THEN RAISE EXCEPTION 'Required field: %',f.label; END IF; CONTINUE; END IF;
 IF f.field_type='number' THEN IF jsonb_typeof(v)<>'number' THEN RAISE EXCEPTION 'Invalid number'; END IF; IF f.settings ? 'min' AND s::numeric<(f.settings->>'min')::numeric OR f.settings ? 'max' AND s::numeric>(f.settings->>'max')::numeric THEN RAISE EXCEPTION 'Number out of range'; END IF;
 ELSIF f.field_type='boolean' THEN IF jsonb_typeof(v)<>'boolean' THEN RAISE EXCEPTION 'Invalid boolean'; END IF;
 ELSE IF jsonb_typeof(v)<>'string' THEN RAISE EXCEPTION 'Invalid text'; END IF; IF length(s)>coalesce((f.settings->>'maxLength')::integer,10000) OR length(s)<coalesce((f.settings->>'minLength')::integer,0) THEN RAISE EXCEPTION 'Invalid length'; END IF;
 IF f.field_type='email' AND s !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Invalid email'; END IF;
 IF f.field_type='url' AND s !~ '^https?://[^[:space:]]+$' THEN RAISE EXCEPTION 'Invalid URL'; END IF;
 IF f.field_type='date' THEN IF s !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'Invalid date'; END IF; PERFORM s::date; END IF;
 IF f.field_type='select' AND NOT (f.settings->'options' ? s) THEN RAISE EXCEPTION 'Invalid option'; END IF;
 IF f.field_type='relationship' THEN target:=s::uuid; IF NOT EXISTS(SELECT 1 FROM public.entities e WHERE e.id=target AND e.organization_id=NEW.organization_id AND e.entity_type_id=(f.settings->>'targetTypeId')::uuid) THEN RAISE EXCEPTION 'Relationship access denied'; END IF; END IF;
 END IF; END LOOP; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_entity_record() FROM PUBLIC,anon;
CREATE TRIGGER validate_metadata_entity BEFORE INSERT OR UPDATE ON public.entities FOR EACH ROW EXECUTE FUNCTION public.validate_entity_record();
CREATE FUNCTION public.publish_entity_configuration(p_org uuid,p_id uuid,p_expected integer,p_config jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE tid uuid; ver integer; f jsonb; oldf record; lay jsonb; k text; action text; BEGIN
 IF NOT public.has_org_role(p_org,ARRAY['owner','admin']) THEN RAISE EXCEPTION 'Configuration access denied'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_org::text,0));
 tid:=coalesce(p_id,gen_random_uuid()); SELECT coalesce(max(version),0) INTO ver FROM public.entity_types WHERE id=tid AND organization_id=p_org;
 IF ver<>p_expected OR (p_id IS NOT NULL AND ver=0) THEN RAISE EXCEPTION 'Configuration changed; reload'; END IF;
 IF jsonb_typeof(p_config->'fields')<>'array' OR jsonb_array_length(p_config->'fields') NOT BETWEEN 1 AND 60 THEN RAISE EXCEPTION 'Invalid fields'; END IF;
 lay:=p_config->'layout'; IF jsonb_typeof(lay)<>'object' THEN RAISE EXCEPTION 'Invalid layout'; END IF;
 FOREACH action IN ARRAY ARRAY['read','create','update','delete'] LOOP IF jsonb_typeof(lay->'permissions'->action)<>'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(lay->'permissions'->action) r WHERE r NOT IN ('owner','admin','member')) THEN RAISE EXCEPTION 'Invalid permissions'; END IF; END LOOP;
 IF ver>0 AND (p_config->>'key')<>(SELECT type_key FROM public.entity_types WHERE id=tid AND version=ver) THEN RAISE EXCEPTION 'Type key is immutable'; END IF;
 INSERT INTO public.entity_types(id,organization_id,version,name,type_key,created_by) VALUES(tid,p_org,ver+1,p_config->>'name',p_config->>'key',auth.uid());
 FOR f IN SELECT * FROM jsonb_array_elements(p_config->'fields') LOOP
 IF (f->>'type')='relationship' AND NOT EXISTS(SELECT 1 FROM public.entity_types WHERE id=(f->'settings'->>'targetTypeId')::uuid AND organization_id=p_org) THEN RAISE EXCEPTION 'Invalid relationship type'; END IF;
 IF (f->>'type')='select' AND (jsonb_typeof(f->'settings'->'options')<>'array' OR jsonb_array_length(f->'settings'->'options')=0) THEN RAISE EXCEPTION 'Options required'; END IF;
 SELECT * INTO oldf FROM public.entity_field_definitions WHERE entity_type_id=tid AND field_key=f->>'key' ORDER BY configuration_version DESC LIMIT 1;
 IF FOUND AND (oldf.field_type<>f->>'type' OR (oldf.field_type='relationship' AND oldf.settings->>'targetTypeId'<>f->'settings'->>'targetTypeId')) THEN RAISE EXCEPTION 'Existing field type is immutable; use a new key'; END IF;
 INSERT INTO public.entity_field_definitions(organization_id,entity_type_id,configuration_version,field_key,label,field_type,required,settings,position) VALUES(p_org,tid,ver+1,f->>'key',f->>'label',f->>'type',coalesce((f->>'required')::boolean,false),coalesce(f->'settings','{}'::jsonb),(SELECT count(*) FROM public.entity_field_definitions WHERE entity_type_id=tid AND configuration_version=ver+1));
 END LOOP;
 FOREACH action IN ARRAY ARRAY['form','detail','columns','filters'] LOOP IF jsonb_typeof(lay->action)<>'array' THEN RAISE EXCEPTION 'Invalid layout fields'; END IF; FOR k IN SELECT jsonb_array_elements_text(lay->action) LOOP IF NOT EXISTS(SELECT 1 FROM public.entity_field_definitions WHERE entity_type_id=tid AND configuration_version=ver+1 AND field_key=k) THEN RAISE EXCEPTION 'Unknown layout field'; END IF; END LOOP; END LOOP;
 IF jsonb_typeof(lay->'tabs')<>'array' THEN RAISE EXCEPTION 'Invalid tabs'; END IF;
 FOR f IN SELECT * FROM jsonb_array_elements(lay->'tabs') LOOP IF length(f->>'label') NOT BETWEEN 1 AND 100 OR jsonb_typeof(f->'fields')<>'array' THEN RAISE EXCEPTION 'Invalid tab'; END IF; FOR k IN SELECT jsonb_array_elements_text(f->'fields') LOOP IF NOT EXISTS(SELECT 1 FROM public.entity_field_definitions WHERE entity_type_id=tid AND configuration_version=ver+1 AND field_key=k) THEN RAISE EXCEPTION 'Unknown tab field'; END IF; END LOOP; END LOOP;
 IF EXISTS(SELECT 1 FROM public.entity_field_definitions WHERE entity_type_id=tid AND configuration_version=ver+1 AND required AND NOT (lay->'form' ? field_key)) THEN RAISE EXCEPTION 'Required fields must appear in form'; END IF;
 INSERT INTO public.entity_type_layouts VALUES(p_org,tid,ver+1,lay);
 INSERT INTO public.audit_logs(organization_id,actor_user_id,action,resource_type,resource_id) VALUES(p_org,auth.uid(),'entity_type.published','entity_type',tid);
 RETURN jsonb_build_object('id',tid,'version',ver+1); END $$;
REVOKE ALL ON FUNCTION public.publish_entity_configuration(uuid,uuid,integer,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.publish_entity_configuration(uuid,uuid,integer,jsonb) TO authenticated;
REVOKE ALL ON public.entity_types,public.entity_field_definitions,public.entity_type_layouts FROM anon;
REVOKE INSERT,UPDATE,DELETE ON public.entity_types,public.entity_field_definitions,public.entity_type_layouts FROM authenticated;
REVOKE ALL ON public.entities FROM anon;